CREATE TABLE eam_inspection_task_equipment (tenant_id BIGINT NOT NULL COMMENT '租户ID',task_id BIGINT NOT NULL COMMENT '点巡检任务ID',equipment_id BIGINT NOT NULL COMMENT '设备ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,task_id,equipment_id),INDEX(tenant_id,equipment_id,task_id),FOREIGN KEY(task_id) REFERENCES eam_inspection_task(id) ON DELETE CASCADE) COMMENT='点巡检任务关联设备，历史身份描述仍保留生成快照';

INSERT INTO eam_inspection_task_equipment SELECT t.tenant_id,t.id,j.equipment_id,MIN(j.n) FROM eam_inspection_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.snapshot,'$.equipment'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,equipment_id BIGINT PATH '$.id' ERROR ON ERROR)) j GROUP BY t.tenant_id,t.id,j.equipment_id;

CREATE TABLE eam_maintenance_task_project (tenant_id BIGINT NOT NULL COMMENT '租户ID',task_id BIGINT NOT NULL COMMENT '任务ID',item_key VARCHAR(255) NOT NULL COMMENT '任务内稳定项目ID',equipment_id BIGINT NULL COMMENT '对应设备ID',source_standard_id BIGINT NULL COMMENT '原标准ID；无法唯一确定的历史记录为空',source_item_key VARCHAR(128) NULL COMMENT '原标准项目ID',type_id BIGINT NULL COMMENT '保养或巡检类型ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,task_id,item_key),INDEX(tenant_id,equipment_id,task_id),INDEX(tenant_id,source_standard_id,source_item_key),FOREIGN KEY(task_id) REFERENCES eam_maintenance_task(id) ON DELETE CASCADE) COMMENT='任务项目ID及来源关联；项目当时的定义为只读快照';

INSERT INTO eam_maintenance_task_project SELECT t.tenant_id,t.id,JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),t.equipment_id,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.sourceStandardId')),'null'),'') AS UNSIGNED),CASE WHEN SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1) REGEXP '^[0-9]+:[^:]+$' THEN CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1),':',1) AS UNSIGNED) ELSE NULL END),CASE WHEN SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1) REGEXP '^[0-9]+:[^:]+$' THEN SUBSTRING_INDEX(SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1),':',-1) ELSE CASE WHEN JSON_EXTRACT(j.value,'$.sourceStandardId') IS NOT NULL THEN SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1) ELSE NULL END END,CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.typeId')),'null'),'') AS UNSIGNED),j.n FROM eam_maintenance_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.snapshot,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j;

CREATE TABLE eam_inspection_task_project (tenant_id BIGINT NOT NULL COMMENT '租户ID',task_id BIGINT NOT NULL COMMENT '任务ID',item_key VARCHAR(255) NOT NULL COMMENT '任务内稳定项目ID',equipment_id BIGINT NULL COMMENT '对应设备ID',source_standard_id BIGINT NULL COMMENT '原标准ID；无法唯一确定的历史记录为空',source_item_key VARCHAR(128) NULL COMMENT '原标准项目ID',type_id BIGINT NULL COMMENT '保养或巡检类型ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,task_id,item_key),INDEX(tenant_id,equipment_id,task_id),INDEX(tenant_id,source_standard_id,source_item_key),FOREIGN KEY(task_id) REFERENCES eam_inspection_task(id) ON DELETE CASCADE) COMMENT='任务项目ID及来源关联；项目当时的定义为只读快照';

INSERT INTO eam_inspection_task_project SELECT t.tenant_id,t.id,JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.equipmentId')),'') AS UNSIGNED),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.sourceStandardId')),'null'),'') AS UNSIGNED),CASE WHEN SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1) REGEXP '^[0-9]+:[^:]+$' THEN CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1),':',1) AS UNSIGNED) ELSE NULL END),CASE WHEN SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1) REGEXP '^[0-9]+:[^:]+$' THEN SUBSTRING_INDEX(SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1),':',-1) ELSE CASE WHEN JSON_EXTRACT(j.value,'$.sourceStandardId') IS NOT NULL THEN SUBSTRING_INDEX(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.id')),'/',-1) ELSE NULL END END,CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.typeId')),'null'),'') AS UNSIGNED),j.n FROM eam_inspection_task t JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(t.snapshot,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j;
